80:   function readProgress() {
81:     try {
82:       const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
83:       return {
84:         streak: safeCount(value.streak), hits: safeCount(value.hits),
85:         best: safeCount(value.best),
86:       };
87:     } catch (_) {
88:       return { streak: 0, hits: 0, best: 0 };
89:     }
90:   }
91: 
92:   function safeCount(value) {
93:     return Number.isSafeInteger(value) && value >= 0 ? Math.min(value, 999999) : 0;
94:   }
95: 
96:   function saveProgress() {
97:     try {
98:       localStorage.setItem(STORAGE_KEY, JSON.stringify({
99:         streak: state.streak, hits: state.hits, best: state.best,
100:       }));
101:     } catch (_) {
102:       // Private browsing or a full storage quota must not interrupt practice.
103:     }
104:   }
105: 
106:   const MIN_TAP_INTERVAL = 250;
107:   const MAX_TAP_INTERVAL = 1500;
108:   const LONG_PAUSE = 2200;
109:   const OUTLIER_TOLERANCE = 0.2;
110: 
111:   function handleTap() {
112:     const now = performance.now();
113:     const hadPreviousTap = state.lastTapAt !== null;
114:     pulseTapButton();
115:     if (state.soundOn) resumeAudio();
116: 
117:     if (state.lastTapAt !== null) {
118:       const interval = now - state.lastTapAt;
119:       if (interval > LONG_PAUSE) {
120:         state.intervals = [];
121:         state.pendingIntervals = [];
122:       } else if (interval >= MIN_TAP_INTERVAL && interval <= MAX_TAP_INTERVAL) {
123:         acceptTapInterval(interval);
124:       } else {
125:         state.pendingIntervals = [];
126:       }
127:     }
128:     state.lastTapAt = now;
129: 
130:     if (!state.bpm) {
131:       ui.tempoCaption.textContent = hadPreviousTap
132:         ? 'Seguí tocando para fijar el pulso'
133:         : 'Tocá al ritmo de tu base';
134:     }
135:     if (navigator.vibrate) navigator.vibrate(8);
136:   }
137: 
138:   function acceptTapInterval(interval) {
139:     const baseline = median(state.intervals);
140:     if (!baseline || Math.abs(interval - baseline) <= baseline * OUTLIER_TOLERANCE) {
141:       state.intervals.push(interval);
142:       state.intervals = state.intervals.slice(-6);
143:       state.pendingIntervals = [];
144:     } else {
145:       const pendingBaseline = median(state.pendingIntervals);
146:       if (!pendingBaseline || Math.abs(interval - pendingBaseline) > pendingBaseline * OUTLIER_TOLERANCE) {
147:         state.pendingIntervals = [interval];
148:       } else {
149:         state.pendingIntervals.push(interval);
150:         if (state.pendingIntervals.length >= 2) {
151:           state.intervals = state.pendingIntervals.slice(-6);
152:           state.pendingIntervals = [];
153:         }
154:       }
155:     }
156: 
157:     if (!state.intervals.length) return;
158:     const previousBpm = state.bpm;
159:     const estimate = estimateBpm(state.intervals);
160:     state.bpm = estimate;
161:     ui.bpm.textContent = String(estimate);
162:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
163:     setTempoReady(true);
164:     if (state.running && previousBpm !== estimate) adjustClockTempo();
165:     else startClock();
166:   }
167: 
168:   function median(values) {
169:     if (!values.length) return null;
170:     const ordered = [...values].sort((a, b) => a - b);
171:     const middle = Math.floor(ordered.length / 2);
172:     return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
173:   }
174: 
175:   function estimateBpm(intervals) {
176:     const average = intervals.reduce((sum, value) => sum + value, 0) / intervals.length;
177:     return Math.max(40, Math.min(240, Math.round(60000 / average)));
178:   }
179: 
180:   function effectiveTempo() {
181:     return state.bpm ? state.bpm * (state.mode === 'doble' ? 2 : 1) : 0;
182:   }
183: 
184:   function setTempoReady(ready) {
185:     ui.tempoStatus.classList.toggle('running', ready && state.running);
186:     ui.tempoStatus.lastChild.textContent = ready ? (state.running ? 'EN MARCHA' : 'LISTO') : 'ESPERANDO';
187:   }
188: 
189:   function updateClockExplanation() {
190:     const modeFactor = state.mode === 'doble' ? 2 : 1;
191:     const hitsPerBeat = state.subdivision * modeFactor;
192:     const hitLabel = hitsPerBeat === 1 ? 'golpe' : 'golpes';
193:     ui.clockExplanation.textContent = `Cuenta: subdivisión ×${state.subdivision} × dinámica ×${modeFactor} = ${hitsPerBeat} ${hitLabel} por pulso base; ${hitsPerBeat * 4} por compás 4/4.`;
194:   }
195: 
196:   function clockGrid(tick) {
197:     const divisions = state.subdivision * (state.mode === 'doble' ? 2 : 1);
198:     return {
199:       divisions,
200:       stepMs: 60000 / state.bpm / divisions,
201:       beat: Math.floor(tick / divisions) % 4,
202:       isAccent: tick % divisions === 0,
203:     };
204:   }
205: 
206:   function startClock() {
207:     if (!state.bpm || state.running) return;
208:     state.running = true;
209:     state.generation += 1;
210:     state.tickNumber = 0;
211:     state.lastTickNumber = -1;
212:     state.lastTickAt = null;
213:     state.clockStepMs = clockGrid(0).stepMs;
214:     state.nextTickAt = performance.now() + 70;
215:     setTempoReady(true);
216:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
217:     scheduleLoop(state.generation);
218:   }
219: 
220:   function clearClockTimers() {
221:     window.clearTimeout(state.timer);
222:     state.tickTimerIds.forEach((id) => window.clearTimeout(id));
223:     state.tickTimerIds.clear();
224:   }
225: 
226:   function adjustClockTempo() {
227:     const now = performance.now();
228:     const oldStepMs = state.clockStepMs || clockGrid(0).stepMs;
229:     const phase = state.lastTickAt === null
230:       ? 0
231:       : Math.max(0, Math.min(1, (now - state.lastTickAt) / oldStepMs));
232:     state.generation += 1;
233:     clearClockTimers();
234:     state.clockStepMs = clockGrid(0).stepMs;
235:     if (state.lastTickNumber < 0) {
236:       state.tickNumber = 0;
237:       state.nextTickAt = now + 70;
238:     } else {
239:       state.tickNumber = state.lastTickNumber + 1;
240:       state.nextTickAt = now + Math.max(8, state.clockStepMs * (1 - phase));
241:     }
242:     scheduleLoop(state.generation);
243:   }
244: 
245:   const CLOCK_LOOKAHEAD_MS = 100;
246:   const CLOCK_LOOP_MS = 25;
247:   const MAX_CLOCK_LATENESS_MS = 50;
248: 
249:   function scheduleLoop(generation) {
250:     if (!state.running || generation !== state.generation) return;
251:     const now = performance.now();
252:     if (state.nextTickAt < now - MAX_CLOCK_LATENESS_MS) {
253:       clearClockTimers();
254:       state.tickNumber = Math.max(0, state.lastTickNumber + 1);
255:       state.nextTickAt = now + 8;
256:     }
257:     while (state.nextTickAt <= now + CLOCK_LOOKAHEAD_MS) {
258:       const scheduledAt = state.nextTickAt;
259:       const tick = state.tickNumber++;
260:       const grid = clockGrid(tick);
261:       queueTick(scheduledAt, tick, grid, generation);
262:       if (state.soundOn) scheduleClick(scheduledAt, grid.isAccent);
263:       state.nextTickAt += grid.stepMs;
264:     }
265:     state.timer = window.setTimeout(() => scheduleLoop(generation), CLOCK_LOOP_MS);
266:   }
267: 
268:   function queueTick(time, tick, grid, generation) {
269:     const delay = Math.max(0, time - performance.now());
270:     const id = window.setTimeout(() => {
271:       state.tickTimerIds.delete(id);
272:       if (!state.running || generation !== state.generation) return;
273:       if (tick <= state.lastTickNumber) return;
274:       if (performance.now() - time > Math.min(state.clockStepMs, MAX_CLOCK_LATENESS_MS)) return;
275:       state.lastTickNumber = tick;
276:       state.lastTickAt = time;
277:       renderBeat(grid.beat, grid.isAccent);
278:       if (grid.isAccent) onMainBeat(grid.beat);
279:     }, delay);
280:     state.tickTimerIds.add(id);
281:   }
282: 
283:   function renderBeat(beat, isAccent) {
284:     ui.beatBoxes.forEach((box, index) => {
285:       box.classList.toggle('active', index === beat && isAccent);
286:       box.classList.toggle('sub-beat', index === beat && !isAccent);
287:     });
288:   }
289: 
290:   function onMainBeat(beat) {
291:     if (beat === 0) {
292:       state.roundNumber += 1;
293:       state.currentPrompt = choosePrompt(state.mode);
294:       state.rhymeRevealed = false;
295:       state.hitThisRound = false;
296:       ui.hit.disabled = true;
297:       ui.round.textContent = `RONDA ${String(state.roundNumber).padStart(2, '0')}`;
298:       ui.promptLabel.textContent = state.mode === 'esdrujulas' ? 'CONCEPTO · ACENTO EN LA ANTEPENÚLTIMA' : 'CONCEPTO · DOBLE TEMPO';
299:       ui.promptIndex.textContent = `#${String(state.roundNumber).padStart(2, '0')}`;
300:       ui.promptWord.textContent = state.currentPrompt.word;
301:       ui.promptWord.classList.remove('pop');
302:       void ui.promptWord.offsetWidth;
303:       ui.promptWord.classList.add('pop');
304:       ui.promptHint.textContent = state.currentPrompt.hint;
305:       ui.instruction.textContent = state.mode === 'doble' ? 'Doblá las sílabas; el remate llega en el pulso 3.' : 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
306:       showEmptyRhymes();
307:     }
308:     if (beat === 2 && state.currentPrompt && !state.rhymeRevealed) revealRhymes();
309:   }
310: 
311:   function choosePrompt(mode) {
312:     const choices = PROMPTS[mode].filter((item) => item !== state.currentPrompt);
313:     return choices[Math.floor(Math.random() * choices.length)] || PROMPTS[mode][0];
314:   }
315: 
316:   function showEmptyRhymes() {
317:     ui.rhymeList.replaceChildren(...Array.from({ length: 4 }, () => {
318:       const chip = document.createElement('span');
319:       chip.className = 'rhyme-chip empty-chip';
320:       chip.textContent = '—';
321:       return chip;
322:     }));
323:     ui.revealNote.textContent = 'APARECE EN EL TIEMPO 3';
324:   }
325: 
326:   function revealRhymes() {
327:     state.rhymeRevealed = true;
328:     ui.rhymeList.replaceChildren(...state.currentPrompt.rhymes.map((word, index) => {
329:       const chip = document.createElement('span');
330:       chip.className = 'rhyme-chip';
331:       chip.textContent = word;
332:       chip.style.transitionDelay = `${index * 45}ms`;
333:       requestAnimationFrame(() => chip.classList.add('visible'));
334:       return chip;
335:     }));
336:     ui.revealNote.textContent = '¡REMATE A TU MANERA!';
337:     ui.hit.disabled = false;
338:   }
339: 
340:   function renderEmptyPrompt() {
341:     ui.round.textContent = 'RONDA 01';
342:     ui.promptLabel.textContent = 'TU CONCEPTO';
343:     ui.promptIndex.textContent = '#01';
344:     ui.promptWord.textContent = 'LISTA';
345:     ui.promptHint.textContent = 'Marcá cuatro pulsos para empezar';
346:     ui.instruction.textContent = 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
347:     ui.hit.disabled = true;
348:     showEmptyRhymes();
349:   }
350: 
351:   function confirmHit() {
352:     if (!state.rhymeRevealed || state.hitThisRound) return;
353:     state.hitThisRound = true;
354:     state.streak += 1;
355:     state.hits += 1;
356:     state.best = Math.max(state.best, state.streak);
357:     updateStats();
358:     saveProgress();
359:     ui.hit.disabled = true;
360:     ui.hit.innerHTML = 'REMATE GUARDADO <span>✓</span>';
361:     window.setTimeout(() => { ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>'; }, 1100);
362:     showToast('Una más para la racha. ¡Buen remate!');
363:   }
364: 
365:   function updateStats() {
366:     ui.streak.textContent = String(state.streak);
367:     ui.hits.textContent = String(state.hits);
368:     ui.best.textContent = String(state.best);
369:   }
370: 
371:   function setMode(mode) {
372:     if (!PROMPTS[mode]) return;
373:     state.mode = mode;
374:     document.body.classList.toggle('mode-double', mode === 'doble');
375:     ui.modeButtons.forEach((button) => {
376:       const active = button.dataset.mode === mode;
377:       button.classList.toggle('active', active);
378:       button.setAttribute('aria-pressed', String(active));
379:     });
380:     updateClockExplanation();
381:     if (state.bpm) ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
382:     restartClockPhase();
383:   }
384: 
385:   function restartClockPhase() {
386:     if (!state.running) return;
387:     state.generation += 1;
388:     clearClockTimers();
389:     state.tickNumber = 0;
390:     state.lastTickNumber = -1;
391:     state.lastTickAt = null;
392:     state.clockStepMs = clockGrid(0).stepMs;
393:     state.nextTickAt = performance.now() + 70;
394:     scheduleLoop(state.generation);
395:   }
396: 
397:   function stopClock() {
398:     state.running = false;
399:     state.generation += 1;
400:     clearClockTimers();
401:     ui.beatBoxes.forEach((box) => box.classList.remove('active', 'sub-beat'));
402:     setTempoReady(Boolean(state.bpm));
403:   }
404: 
405:   function resetSession() {
406:     stopClock();
407:     state.lastTapAt = null;
408:     state.intervals = [];
409:     state.pendingIntervals = [];
410:     state.bpm = null;
411:     state.roundNumber = 0;
412:     state.currentPrompt = null;
413:     state.rhymeRevealed = false;
414:     state.hitThisRound = false;
415:     state.streak = 0;
416:     state.hits = 0;
417:     ui.bpm.textContent = '—';
418:     ui.tempoCaption.textContent = 'Tocá al ritmo de tu base';
419:     ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>';
420:     renderEmptyPrompt();
421:     updateStats();
422:     saveProgress();
423:     showToast('Sesión reiniciada. El récord queda guardado.');
424:   }
425: 
426:   function pulseTapButton() {
427:     ui.tap.classList.add('pulse');
428:     window.setTimeout(() => ui.tap.classList.remove('pulse'), 110);
429:   }
430: 
431:   function toggleSound() {
432:     state.soundOn = !state.soundOn;
433:     if (state.soundOn) resumeAudio();
434:     updateSoundButton();
435:     showToast(state.soundOn ? 'Metrónomo sonoro activado.' : 'Metrónomo sonoro silenciado.');
436:   }
437: 
438:   function updateSoundButton() {
439:     ui.sound.classList.toggle('active', state.soundOn);
440:     ui.sound.setAttribute('aria-pressed', String(state.soundOn));
441:     ui.sound.setAttribute('aria-label', state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro');
442:     ui.sound.title = state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro';
443:   }
444: 
445:   function resumeAudio() {
446:     const AudioContextClass = window.AudioContext || window.webkitAudioContext;
447:     if (!AudioContextClass) return;
448:     try {
449:       if (!state.audio) state.audio = new AudioContextClass();
450:       if (state.audio.state === 'suspended') state.audio.resume();
451:     } catch (_) {
452:       // Visual timing remains available if Web Audio is unavailable.
453:     }
454:   }
455: 
456:   function scheduleClick(time, accented) {
457:     if (!state.audio || state.audio.state !== 'running') return;
458:     try {
459:       const oscillator = state.audio.createOscillator();
460:       const gain = state.audio.createGain();
461:       const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
462:       oscillator.type = 'sine';
463:       oscillator.frequency.value = accented ? 880 : 590;
464:       gain.gain.setValueAtTime(0.0001, start);
465:       gain.gain.exponentialRampToValueAtTime(accented ? 0.11 : 0.055, start + 0.004);
466:       gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.045);
467:       oscillator.connect(gain);
468:       gain.connect(state.audio.destination);
469:       oscillator.start(start);
470:       oscillator.stop(start + 0.05);
471:       oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
472:     } catch (_) {
473:       // A missed sound must not stop the visual beat scheduler.
474:     }
475:   }
476: 
477:   function showToast(message) {
478:     ui.toast.textContent = message;
479:     ui.toast.classList.add('show');
480:     window.clearTimeout(state.toastTimer);
481:     state.toastTimer = window.setTimeout(() => ui.toast.classList.remove('show'), 1900);
482:   }
