484:   function handleYouTubeSubmit(event) {
485:     event.preventDefault();
486:     const media = parseYouTubeUrl(ui.url.value);
487:     if (!media) {
488:       ui.playerStatus.textContent = 'Ese link no parece un video o playlist compatible de YouTube.';
489:       ui.url.focus();
490:       return;
491:     }
492:     state.pendingMedia = media;
493:     ui.playerFrame.hidden = false;
494:     ui.playerStatus.textContent = media?.type === 'playlist' ? 'Preparando playlist de YouTube…' : 'Preparando video de YouTube…';
495:     if (state.player) {
496:       try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
